SOURCE_CLAIM_JSON: {"title":"Realiza INE declaratoria de resultados del proceso de Revocación de Mandato","publisher":"Instituto Nacional Electoral","publication_date":"2022-04-11","url":"https://centralelectoral.ine.mx/2022/04/11/realiza-ine-declaratoria-de-resultados-del-proceso-de-revocacion-de-mandato/","claim":"The INE completed the 2022 recall referendum count and stated that it guaranteed registered voters' ability to vote freely; participation was 16,502,636 voters, or 17.77% of the electoral roll.","locator":"Lines 160 and 190-192","provisional_id":"E-AMLO22-4B-01","canonical_fact_key":"https://centralelectoral.ine.mx/2022/04/11/realiza-ine-declaratoria-de-resultados-del-proceso-de-revocacion-de-mandato/|160,190-192|INE recall process and participation","disposition":"final_evidence","chapter_ids":["4B"],"methodology_ids":["4B.1","4B.2","4B.8","4B.10"],"source_type":"official election-body record","source_confidence":"high","source_confidence_reason":"Primary INE declaration and official count.","final_evidence_use":"final_evidence","period_fit":"Directly dated 11 April 2022.","ruler_attribution":"The process tested the incumbent President, but administration of the vote was institutionally assigned to the INE.","contrary_evidence":["Low participation limited the referendum's democratic significance; the INE's institutional self-description is not an independent evaluation of all campaign conditions."],"lenses":["4B.1","4B.2","4B.8","4B.10"]}

SOURCE_CLAIM_JSON: {"title":"Mexico: The April 10, 2022 Revocation of Mandate Referendum","publisher":"Delian Project using official INE results","publication_date":"2022-04-13","url":"https://www.ine.mx/wp-content/uploads/2022/04/Mexico-The-April-10-2022-Revocation-of-Mandate-Referendum-Delian-Project-Final-April-13-2022.pdf","claim":"The recall referendum drew 17.7% participation, below the 40% legal threshold; 91.8% of participants voted for AMLO to continue, but the report judged the result legally nonbinding and of limited participatory-democratic value.","locator":"PDF pp. 20-22, lines 481-523","provisional_id":"E-AMLO22-4B-02","canonical_fact_key":"https://www.ine.mx/wp-content/uploads/2022/04/Mexico-The-April-10-2022-Revocation-of-Mandate-Referendum-Delian-Project-Final-April-13-2022.pdf|pp.20-22|recall turnout and legal threshold","disposition":"final_evidence","chapter_ids":["4B"],"methodology_ids":["4B.1","4B.2","4B.8"],"source_type":"electoral observation and analysis","source_confidence":"high","source_confidence_reason":"Uses 100% official INE results and distinguishes numerical outcome from legal effect.","final_evidence_use":"final_evidence","period_fit":"Directly covers the 10 April 2022 referendum.","ruler_attribution":"The referendum concerned AMLO, while turnout and administration involved parties, INE, Congress, courts, and voters.","contrary_evidence":["The result shows that the constitutional recall mechanism operated and that the incumbent remained subject to a formal challenge."],"lenses":["4B.1","4B.2","4B.8"]}

SOURCE_CLAIM_JSON: {"title":"Freedom in the World 2022: Mexico","publisher":"Freedom House","publication_date":"2022","url":"https://freedomhouse.org/country/mexico/freedom-world/2022","claim":"Freedom House reported that Morena retained a lower-house majority but lost its prior supermajority, while AMLO continued verbally attacking critics, media, civil-society organizations, and autonomous institutions.","locator":"Lines 84-94","provisional_id":"E-AMLO22-4B-03","canonical_fact_key":"https://freedomhouse.org/country/mexico/freedom-world/2022|84-94|Morena majority and executive attacks on critics","disposition":"final_evidence","chapter_ids":["4B"],"methodology_ids":["4B.1","4B.3","4B.4","4B.5","4B.6","4B.10"],"source_type":"comparative democracy assessment","source_confidence":"medium_high","source_confidence_reason":"Established comparative-monitoring organization covering elections, institutions, and political rhetoric.","final_evidence_use":"final_evidence","period_fit":"2022 country assessment with 2021 electoral context and ongoing administration behavior.","ruler_attribution":"Strong attribution for presidential rhetoric; legislative composition and opposition strength were election-mediated and institutionally distributed.","contrary_evidence":["The loss of the supermajority indicates that electoral competition and institutional constraints remained meaningful."],"lenses":["4B.1","4B.3","4B.4","4B.5","4B.6","4B.10"]}

SOURCE_CLAIM_JSON: {"title":"La muerte judicial del “Plan B”: certeza inmediata y riesgos futuros","publisher":"Instituto de Investigaciones Jurídicas, Universidad Nacional Autónoma de México","publication_date":"2024-05-06","url":"https://www.scielo.org.mx/pdf/es/v42/2448-6442-es-42-e2545.pdf","claim":"The academic study describes AMLO's 2022-2023 Plan B electoral reform as a profound proposed transformation of the electoral system; both parts were challenged, suspended, and ultimately invalidated by the Supreme Court, although the Court relied on legislative-procedure violations rather than deciding all substantive issues.","locator":"PDF pp. 1-2, lines 12-31 and 41-80","provisional_id":"E-AMLO22-4B-04","canonical_fact_key":"https://www.scielo.org.mx/pdf/es/v42/2448-6442-es-42-e2545.pdf|pp.1-2|Plan B reform and Supreme Court invalidation","disposition":"context","chapter_ids":["4B"],"methodology_ids":["4B.2","4B.4","4B.5","4B.8","4B.10"],"source_type":"peer-reviewed legal-political analysis","source_confidence":"high","source_confidence_reason":"Academic legal analysis from UNAM's legal-research institute with explicit procedural distinctions.","final_evidence_use":"context","period_fit":"The reform began in December 2022, while final judicial invalidation occurred later; post-period material is used only to establish the fate of the 2022 initiative.","ruler_attribution":"The proposal is directly attributed to AMLO; congressional passage and judicial review were shared institutional processes.","contrary_evidence":["The Court's procedural basis means the source does not establish that every substantive reform provision was unconstitutional."],"lenses":["4B.2","4B.4","4B.5","4B.8","4B.10"]}

SOURCE_CLAIM_JSON: {"title":"Mexico: ARTICLE 19 condemns continued assault on its work and the press","publisher":"ARTICLE 19","publication_date":"2022-12-01","url":"https://www.article19.org/resources/mexico-article-19-condemns-continued-assault-on-its-work-and-the-press/","claim":"ARTICLE 19 described Mexico's 2022 press environment as hostile, reported an attack against journalists approximately every 14 hours and 12 work-related journalist murders, and linked the environment to stigmatizing discourse from those in power.","locator":"Lines 55-65","provisional_id":"E-AMLO22-4B-05","canonical_fact_key":"https://www.article19.org/resources/mexico-article-19-condemns-continued-assault-on-its-work-and-the-press/|55-65|2022 press attacks and stigmatizing discourse","disposition":"final_evidence","chapter_ids":["4B"],"methodology_ids":["4B.3","4B.5","4B.6","4B.7","4B.10"],"source_type":"press-freedom monitoring","source_confidence":"high","source_confidence_reason":"Contemporaneous organization report with defined annual counts and source methodology described by the organization.","final_evidence_use":"final_evidence","period_fit":"Published 1 December 2022 and reports on the target year.","ruler_attribution":"Press violence has mixed criminal, local, and federal causes; stigmatizing executive discourse is attributable at branch level, not proof of personal incitement to each attack.","contrary_evidence":["The source does not establish that every journalist killing or attack was caused by federal authorities."],"lenses":["4B.3","4B.5","4B.6","4B.7","4B.10"]}

SOURCE_CLAIM_JSON: {"title":"Mexico: Freedom on the Net 2022 Country Report","publisher":"Freedom House","publication_date":"2022","url":"https://freedomhouse.org/country/mexico/freedom-net/2022","claim":"Freedom House reported that Pegasus spyware had been used against people investigating government corruption and human-rights abuses, with Mexican journalists, politicians, lawyers, activists, and political figures among documented or suspected targets.","locator":"Lines 391 and linked evidence notes","provisional_id":"E-AMLO22-4B-06","canonical_fact_key":"https://freedomhouse.org/country/mexico/freedom-net/2022|391|Pegasus targeting of critical voices in Mexico","disposition":"final_evidence","chapter_ids":["4B"],"methodology_ids":["4B.3","4B.6","4B.9"],"source_type":"internet-freedom assessment","source_confidence":"medium_high","source_confidence_reason":"Comparative report synthesizing forensic and investigative evidence from Amnesty, Forbidden Stories, Citizen Lab, and media partners.","final_evidence_use":"final_evidence","period_fit":"2022 country report; some underlying surveillance events predate 2022.","ruler_attribution":"Institutional surveillance is not automatically personal presidential conduct; it bears on the administration-era information environment and accountability.","contrary_evidence":["The report includes historical cases and does not establish that AMLO personally ordered surveillance."],"lenses":["4B.3","4B.6","4B.9"]}

SOURCE_CLAIM_JSON: {"title":"Mexico: Freedom on the Net 2023 Country Report","publisher":"Freedom House","publication_date":"2023","url":"https://freedomhouse.org/country/mexico/freedom-net/2023","claim":"A joint Citizen Lab-R3D investigation found that two Centro PRODH human-rights defenders were targeted by Pegasus between June and September 2022, while the report identified probable links to state actors and the military.","locator":"Lines 464-477","provisional_id":"E-AMLO22-4B-07","canonical_fact_key":"https://freedomhouse.org/country/mexico/freedom-net/2023|464-477|Centro PRODH Pegasus targeting in 2022","disposition":"final_evidence","chapter_ids":["4B"],"methodology_ids":["4B.3","4B.6","4B.9"],"source_type":"digital-forensics and internet-freedom report","source_confidence":"high","source_confidence_reason":"Named forensic investigation by Citizen Lab and R3D with target identities and dates; presidential knowledge remains unresolved.","final_evidence_use":"final_evidence","period_fit":"The report covers June 2022-May 2023 and identifies specific June-September 2022 events.","ruler_attribution":"Strong administration-era and probable military attribution; no evidence of AMLO's personal authorization.","contrary_evidence":["The report uses probable-link language and does not constitute a final judicial finding."],"lenses":["4B.3","4B.6","4B.9"]}

SOURCE_CLAIM_JSON: {"title":"For Mexican journalists, President López Obrador’s pledge to curb spyware rings hollow","publisher":"Committee to Protect Journalists","publication_date":"2022-10","url":"https://cpj.org/2022/10/mexican-journalists-lopez-obradors-pledge-curb-spyware-hollow/","claim":"CPJ reported that a 2022 joint investigation found Pegasus infections on two Mexican journalists and a human-rights defender despite AMLO's earlier pledge to end illegal surveillance, and said little had changed since 2017.","locator":"Lines 517-520","provisional_id":"E-AMLO22-4B-08","canonical_fact_key":"https://cpj.org/2022/10/mexican-journalists-lopez-obradors-pledge-curb-spyware-hollow/|517-520|spyware evidence versus presidential pledge","disposition":"final_evidence","chapter_ids":["4B"],"methodology_ids":["4B.3","4B.6","4B.9"],"source_type":"press-freedom analysis","source_confidence":"medium_high","source_confidence_reason":"CPJ reports a named joint forensic investigation and contrasts it with a public presidential commitment.","final_evidence_use":"final_evidence","period_fit":"Published in October 2022; underlying infections occurred in 2019-2021 and were disclosed during 2022.","ruler_attribution":"Directly relevant to the administration's stated policy and accountability gap, but not proof of AMLO ordering surveillance.","contrary_evidence":["The infections predate the target year and the source does not establish which agency or official authorized them."],"lenses":["4B.3","4B.6","4B.9"]}

SOURCE_CLAIM_JSON: {"title":"La CIDH, su RELE y ONU-DH México manifiestan preocupación ante nuevos hallazgos sobre la utilización del software Pegasus","publisher":"UN Office of the High Commissioner for Human Rights in Mexico, IACHR Special Rapporteurship, and OHCHR","publication_date":"2022 (page date not visible in accessible excerpt)","url":"https://hchr.org.mx/comunicados/la-cidh-su-rele-y-onu-dh-mexico-manifiestan-preocupacion-ante-nuevos-hallazgos-sobre-la-utilizacion-del-software-pegasus/","claim":"The regional and UN human-rights bodies recalled evidence that Mexican government spyware had targeted journalists, human-rights defenders, lawyers, health experts, and anti-corruption actors, and emphasized the freedom-of-expression implications.","locator":"Spanish page lines 94-96 and linked 2017 IACHR statement","provisional_id":"E-AMLO22-4B-09","canonical_fact_key":"https://hchr.org.mx/comunicados/la-cidh-su-rele-y-onu-dh-mexico-manifiestan-preocupacion-ante-nuevos-hallazgos-sobre-la-utilizacion-del-software-pegasus/|94-96|UN and IACHR concern over Mexican spyware","disposition":"context","chapter_ids":["4B"],"methodology_ids":["4B.3","4B.6","4B.9"],"source_type":"UN and regional human-rights communication","source_confidence":"high","source_confidence_reason":"Institutional human-rights bodies with prior documented cases and formal freedom-of-expression mandate.","final_evidence_use":"context","period_fit":"The accessible passage concerns earlier cases and provides institutional background rather than a clean 2022 event record.","ruler_attribution":"Context for inherited surveillance practices; not direct proof of AMLO-era authorization.","contrary_evidence":["The cited historical allegations largely concern 2015-2016 and cannot by themselves establish 2022 conduct."],"lenses":["4B.3","4B.6","4B.9"]}

SOURCE_CLAIM_JSON: {"title":"Freedom in the World 2022: Mexico","publisher":"Freedom House","publication_date":"2022","url":"https://freedomhouse.org/country/mexico/freedom-world/2022","claim":"Freedom House described Mexico as electorally competitive enough for Morena to lose its lower-house supermajority, while reporting continued inflammatory attacks by the President against critics, media, civil society, and autonomous institutions.","locator":"Lines 84-94","provisional_id":"E-AMLO22-4B-10","canonical_fact_key":"https://freedomhouse.org/country/mexico/freedom-world/2022|84-94|electoral competition and executive attacks","disposition":"final_evidence","chapter_ids":["4B"],"methodology_ids":["4B.1","4B.3","4B.4","4B.5","4B.6","4B.10"],"source_type":"comparative democracy assessment","source_confidence":"medium_high","source_confidence_reason":"Established comparative-monitoring organization assessing elections, institutions, rhetoric, and media conditions.","final_evidence_use":"final_evidence","period_fit":"2022 assessment using the 2021 midterm election and continuing executive behavior.","ruler_attribution":"Presidential rhetoric is directly attributable; electoral outcomes and autonomous institutions remain institutionally separate.","contrary_evidence":["The loss of the supermajority and continued autonomous institutions indicate meaningful constraints and contestability."],"lenses":["4B.1","4B.3","4B.4","4B.5","4B.6","4B.10"]}

